[4767] = {"Jinete del viento", nil, {"Consigue 10 huevos de dracole√≥n Nido Alto para Elu en el Poblado Viento Libre."}},
[4768] = {"La tablilla de Rocanegra", nil, {"Ll√©vale la tablilla de Rocanegra a la maga oscura Vivian Lagrave en Kargath."}},
