[4770] = {"De vuelta a casa", nil, {"Saca a Pao'ka Monte Presto de Nido Alto y despu√©s habla con Motega Crin de Fuego en Campamento del Tramo Blanco."}},
[4771] = {"Gambito del Alba", nil, {"Coloca el Gambito del Alba en la Sala de la Visi√≥n de Scholomance. Derrota a Vectus y ve a ver a Betina Bigglezink."}},
